import{_ as i,o as a,c as h,a2 as k}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Linnet","text":"A typed tensor language","tagline":"Write a model once as checked, weight-free source. Run it in PyTorch, JAX, XLA, or ONNX Runtime — and bring models back from all of them.","image":{"src":"/logo.svg","alt":"Linnet"},"actions":[{"theme":"brand","text":"Get started","link":"/guide/installation"},{"theme":"alt","text":"Coming from PyTorch","link":"/guide/from-pytorch"},{"theme":"alt","text":"Examples","link":"/examples/"}]},"features":[{"title":"Shapes checked before anything runs","details":"Every dimension is a symbol the compiler reasons about. A reshape that does not preserve the element count, an attention head split that does not divide, a mismatched dtype — all reported at check time with the shapes involved, never as a runtime error."},{"title":"Source without payload","details":"A .linnet file declares parameters and never contains tensor data. Checking or inspecting a package executes nothing, and weights bind by path from SafeTensors — no pickle, no model classes to trust."},{"title":"One model, every framework","details":"The same source materializes as a torch.nn.Module, a jax function or Flax NNX module, a StableHLO module for XLA, or an ONNX model. Exporters recover softmax, norms, and activations from framework graphs back into library calls."},{"title":"Index notation","details":"Contractions and reductions are written as indexed expressions with compile-time domains — sum[k] a[i, k] * b[k, j] — and lowered to broadcasts, gathers, and reductions, or matched to native kernels."},{"title":"A standard library in Linnet","details":"linear, embedding, softmax, rms_norm, layer_norm, rope, attention, swiglu are ordinary source the checker verifies like any other. The compiler knows no model names."},{"title":"Tooling from day one","details":"Formatter, linter, language server (VS Code, Neovim), executable spec tests, an optimizer with an e-graph superoptimizer, and linnet explain to see what it did."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1790149373000}'),n={name:"index.md"};function t(l,s,p,e,F,r){return a(),h("div",null,[...s[0]||(s[0]=[k("",5)])])}const y=i(n,[["render",t]]);export{g as __pageData,y as default};
